contract DAO {
    // Project Proposal Module
    struct Proposal {
        string description;
        uint256 budget;
        uint256 timeline;
    }

    mapping (uint256 => Proposal) public proposals;

    function proposeProject(string memory _description, uint256 _budget, uint256 _timeline) public {
        proposals[proposalCount] = Proposal(_description, _budget, _timeline);
        proposalCount++;
    }

    // Voting Module
    struct Vote {
        uint256 proposalId;
        uint256 tokensAllocated;
    }

    mapping (uint256 => Vote) public votes;

    function voteOnProposal(uint256 _proposalId, uint256 _tokensAllocated) public {
        votes[_proposalId].proposalId = _proposalId;
        votes[_proposalId].tokensAllocated = _tokensAllocated;
    }

    // Funding Module
